function start(number, title, overview, pages) {
  week = { schemaVersion: 1, id: `w${String(number).padStart(2,'0')}`, number, exam: 'midterm', title, overview,
    source: { filename: `[교안]인터넷보안_${String(number).padStart(2,'0')}.pdf`, pages }, objectives: [], questions: [], coverage: [], corrections: [], references: [] };
  weeks.push(week);
}
function obj(slug, title, pages, why, explanation, takeaway, comparison, situation, steps, answer, mistake, checkPrompt, checkAnswer, correctionIds=[]) {
  objective = { id: `${week.id}-${slug}`, title, pages, why, explanation, keyTakeaway: takeaway,
    comparison: comparison.map(([term,meaning,example])=>({term,meaning,example})),
    workedExample: { situation, steps, answer }, commonMistakes: [mistake], check: { prompt: checkPrompt, answer: checkAnswer }, prerequisites: [], correctionIds: correctionIds.map(x=>`${week.id}-correction-${x}`) };
  week.objectives.push(objective);
}
function q(family, kind, difficulty, pages, prompt, choices) {
  // Exactly one authored question per call; first authored choice is correct.
  const n=week.questions.length+1, shift=(n-1)%4;
  const ordered=choices.slice(4-shift).concat(choices.slice(0,4-shift));
  const options=ordered.map(([text,explanation],i)=>({id:'abcd'[i],text,explanation}));
  week.questions.push({id:`${week.id}-q${String(n).padStart(3,'0')}`,objectiveId:objective.id,family:`${week.id}-${family}`,kind,difficulty,prompt,options,answerId:'abcd'[shift],explanation:choices[0][1],sourcePages:pages});
}
function correction(id, pages, issue, corrected, examGuidance, status, referenceKeys) {
  week.corrections.push({id:`${week.id}-correction-${id}`,pages,issue,corrected,examGuidance,status,references:referenceKeys.map(k=>refs[k])});
}
function coverage(entries) {
  week.coverage=entries.map(([page,topic,slugs,status='covered',note='본문과 해당 문항으로 학습하며 구형 제품 예시는 정정 기록의 적용 범위를 따른다.'])=>({pages:[page],topic,objectiveIds:slugs.map(s=>`${week.id}-${s}`),status,note}));
}
