q('account-default','concept',1,[12,13],'필요한 기본 관리 계정을 유지해야 할 때 가장 타당한 조합은?',[
  ['고유 인증정보·책임자·필요한 권한·사용 감사','기본값 노출과 과도한 사용을 함께 줄이고 책임을 남기는 조합이다.'],['기본 비밀번호 유지와 이름 숨기기','이름의 비공개만으로 알려진 인증정보 위험이 사라지지 않는다.'],['로그 제거와 공용 사용','오용을 알아차리고 책임을 추적하기 어려워진다.'],['네트워크 포트만 변경','우연한 탐색을 줄일 수 있어도 인증과 권한 문제는 남는다.']]);
q('account-review-proof','evidence',2,[7,8],'불필요한 계정이 없다는 점검에 가장 직접적인 근거는?',[
  ['계정 목록과 담당자·재직·업무 필요성의 대조','계정이 필요한 이유와 실제 소유자를 검증해야 불필요 여부를 판단할 수 있다.'],['모든 비밀번호가 복잡도 규칙을 통과했다는 결과','인증정보 강도와 계정의 업무 필요성은 별개다.'],['암호화된 테이블 목록만 확인','저장 보호 대상은 퇴직자·만료 계정의 잔존 여부를 보여주지 않는다.'],['전체 계정 개수 하나','같은 개수라도 구성원과 필요성이 다를 수 있다.']]);
obj('authentication-policy','실패 제한과 비밀번호 정책의 목적',[9,10,11,12,13],
  '단순한 잠금 숫자나 문자 혼합 규칙만 외우면 공격자는 느려져도 정상 사용자가 업무를 못 하는 정책을 만들 수 있다.',
  ['온라인 추측 공격은 서버가 받아 주는 시도 횟수에 영향을 받으므로 실패 제한과 지연은 시도를 줄이는 수단이다. 그러나 공격자가 다른 사람 계정을 반복 실패시켜 잠글 수 있어 복구 절차와 관찰이 필요하다. 교안의 3·5·10회는 서로 다른 예시이며 모든 환경에 동시에 적용할 보편적인 수치가 아니다.',
   '교안의 짧은 혼합 비밀번호와 정기 변경 예시는 과거 점검 맥락이다. 현대 보충에서는 충분한 길이, 유출·상용 비밀번호 차단, 안전한 전송과 저장, 다중요소 인증을 함께 고려한다. NIST 지침을 국내 모든 DB의 법정 기준으로 바꾸어 말하지 않으며 DBMS 버전별 검증 기능도 확인한다.'],
  '추측 비용을 높이면서 정상 사용자의 복구 가능성을 보존하고 적용 기준의 버전을 표시한다.',
  [['실패 제한','온라인 시도량 통제','연속 실패 후 지연'],['비밀번호 검증','선택한 비밀번호의 취약성 점검','유출된 값 거절']],
  '비밀번호를 매달 바꾸지만 사용자들이 끝자리 숫자만 바꾸고 있다.',
  ['변경 주기 준수 여부와 실제 추측 난이도를 구분한다.','적용 정책 범위를 확인하고 긴 고유 비밀번호·차단 목록·다중요소 인증과 침해 시 변경을 검토한다.'],
  '달력상의 변경 횟수만으로 인증 강도를 평가하지 않는다.',
  '잠금은 무조건 짧을수록 안전하다는 생각은 타인의 계정 잠금을 유발하는 서비스 거부를 놓친다.',
  '암호 복잡도 플러그인 이름을 다른 MySQL 버전에 그대로 적용해도 될까?', '버전의 지원 기능과 설치 방식을 확인해야 한다. 8.4 문서는 검증 컴포넌트를 설명한다.', ['password','db-version']);
q('auth-lockout-tradeoff','application',2,[9,13],'실패 한 번에 계정을 장기간 잠그는 정책의 주요 부작용은?',[
  ['타인이 실패를 유발해 정상 이용을 막을 수 있다','시도 제한은 추측을 늦추지만 외부인이 계정 잠금을 유발할 수 있어 복구와 지연 정책을 함께 설계해야 한다.'],['비밀번호가 자동으로 공개된다','잠금 자체가 비밀번호를 출력하지 않는다.'],['저장 암호화가 해제된다','인증 실패 정책과 저장 암호화는 다른 통제다.'],['모든 오프라인 추측도 차단된다','유출된 검증값을 대상으로 한 오프라인 시도에는 서버 잠금이 적용되지 않는다.']]);
q('auth-modern-guidance','contrast',2,[10,12,13],'교안의 정기 비밀번호 변경 예시를 학습 앱에서 설명하는 적절한 방식은?',[
  ['과거 예시로 표시하고 현대 지침의 조건을 구분한다','정기 변경의 보편적 강제와 침해 증거가 있을 때의 변경은 다르다. 지침의 적용 범위도 밝혀야 한다.'],['월별 변경을 모든 서비스의 영구 기준으로 채점한다','현재 지침 및 적용 환경과 충돌하는 일반화다.'],['비밀번호는 절대 변경하지 않아도 된다고 가르친다','침해나 초기 공유 등 변경이 필요한 조건을 놓친다.'],['혼합 문자만 있으면 유출된 값도 허용한다','구성 규칙 통과가 알려진 비밀번호의 안전성을 보장하지 않는다.']]);
q('auth-component-version','evidence',1,[11],'MySQL 8.4에 5.6 시절의 검증 플러그인 설치 예시를 적용하려 한다. 먼저 할 일은?',[
  ['8.4 공식 문서의 검증 컴포넌트 지원 방식 확인','기능 목적이 같아도 설치 단위와 설정이 변할 수 있어 지원 버전을 대조해야 한다.'],['시스템 권한 테이블을 직접 덮어쓰기','구버전 예시의 강제 적용은 지원되지 않는 변경과 장애를 낳을 수 있다.'],['버전 번호를 문서에서 삭제','차이를 숨기면 적용 가능성을 판단할 수 없다.'],['검증 기능이 영원히 없다고 결론','옛 플러그인과 현대 컴포넌트의 차이를 무시한 결론이다.']]);
obj('environment-separation','개발·운영 분리와 시험 데이터',[14],
  '개발자의 편의를 위해 운영 자료와 권한을 복제하면 시험 환경의 약한 통제가 실제 개인정보의 유출 경로가 된다.',
  ['개발과 운영은 사용자, 권한, 네트워크 연결, 인증정보와 데이터의 경계를 나누어야 한다. 교안은 하드웨어 분리를 강하게 요구하는 점검 예시를 제시한다. 현대 환경에 적용할 때는 적용 규정과 위험에 따라 물리적 또는 논리적 격리의 충족 여부를 검토해야 하며 단순히 서버 이름이 다르다는 것으로 충분하지 않다.',
   '시험 자료는 가능한 한 가상 자료를 사용하고 필요한 실제 자료는 승인된 삭제·마스킹·비식별 검토를 거쳐 최소화한다. 운영 연결 정보가 개발 환경에 남으면 분리한 서버 사이에 다시 길이 생긴다. 분리의 성과는 개발 환경이 침해되었을 때 운영 접속과 실자료 접근이 실제로 제한되는지로 확인한다.'],
  '서버 구분과 함께 권한·연결·데이터 이동 경계를 검증한다.',
  [['환경 분리','업무 영역 사이 영향 제한','개발 계정의 운영 접근 제한'],['데이터 최소화','시험에 필요한 정보만 제공','가상 고객으로 테스트']],
  '시험 서버는 별도 장비지만 운영 DB의 관리자 비밀번호가 배포되어 있다.',
  ['장비 분리와 운영 접속 권한을 별도 항목으로 평가한다.','운영 인증정보를 제거·교체하고 시험용 데이터와 계정으로 업무가 가능한지 검증한다.'],
  '장비가 달라도 운영 권한이 공유되면 격리 목적이 훼손된다.',
  '시험 환경은 외부 서비스가 아니니 실자료를 무제한 복사해도 된다는 생각은 내부 유출 경로를 놓친다.',
  '환경 이름만 dev와 prod로 바꾸면 분리가 성립할까?', '아니다. 실제 연결·권한·인증정보와 데이터 이동을 점검해야 한다.', ['separation']);
q('separation-credential','application',2,[14],'개발·운영 서버를 분리했지만 같은 DBA 인증정보를 쓴다. 핵심 문제는?',[
  ['개발 환경 침해가 운영 권한으로 이어질 수 있음','장비 경계를 나누어도 공유 인증정보가 운영으로의 접속 경로를 만든다.'],['서버 두 대가 있으므로 문제없음','서버 수는 인증 경계의 증거가 아니다.'],['데이터 형식이 무조건 달라짐','장비 분리는 데이터 형식을 자동 변경하지 않는다.'],['감사 로그가 자동 암호화됨','환경 분리와 로그 암호화는 별도 구성이다.']]);
q('separation-test-data','application',1,[14],'기능 시험에 실제 고객 신원이 필요하지 않다. 적절한 데이터 선택은?',[
  ['가상 자료로 시험하고 필요한 예외만 승인·최소화','목적에 불필요한 실제 정보를 옮기지 않으면 유출 피해의 원천을 줄일 수 있다.'],['운영 DB 전체를 매일 복사','시험 목적을 넘는 자료 이동과 노출을 만든다.'],['관리자 계정도 함께 복사','자료 검증과 무관한 과도한 권한을 확산한다.'],['파일 이름만 익명이라고 변경','내용 속 개인 정보가 그대로라면 익명화가 아니다.']]);
q('separation-verification','evidence',2,[14],'개발 계정으로 운영 DB 접근이 제한된다는 가장 직접적인 확인은?',[
  ['승인된 시험에서 접근 거부 결과와 적용 권한·경로 대조','설정 의도가 실제 연결과 인가에 반영되는지 확인하는 증거다.'],['개발과 운영의 서버 이름이 다름을 확인','명칭 구분은 실제 인증정보·네트워크 경계의 증거가 아니다.'],['두 서버의 IP가 서로 다름을 확인','주소가 달라도 개발 계정에 운영 접속이 허용될 수 있다.'],['DB 파일이 암호화되었다는 결과만 확인','저장 암호화는 개발 계정의 정상 조회 권한을 거부하는 통제와 다르다.']]);
obj('public-privileges','PUBLIC 권한의 확산 범위',[15],
  '공용 범위에 준 권한은 새 사용자가 생길 때도 뜻밖에 전달될 수 있다. 한 계정의 권한만 줄여서는 해결되지 않는다.',
  ['PUBLIC은 제품에 따라 모든 사용자에게 적용되는 공통 권한 범위를 나타낸다. 필요 없는 테이블 조회나 관리 권한이 여기에 있으면 개별 계정이 제한되어 보여도 넓게 접근할 수 있다. 점검에서는 직접 부여와 역할을 통한 간접 부여를 모두 살펴야 한다.',
   '권한을 회수할 때는 애플리케이션이 실제로 사용하는 기본 기능과 구분하여 영향도를 시험한다. PUBLIC 자체를 없애거나 모든 권한을 일괄 제거하는 것은 제품 동작을 깨뜨릴 수 있다. 필요한 업무 권한은 명시적인 역할이나 전용 계정으로 좁혀 부여하고 변경 후 정상·거부 경로를 확인한다.'],
  '모두에게 주는 권한일수록 업무 필요성을 엄격하게 검토한다.',
  [['공통 권한','여러 사용자에게 넓게 적용','PUBLIC의 불필요한 조회'],['명시적 업무 역할','직무별로 범위 제한','보고 담당 역할의 조회']],
  '새로 만든 최소권한 계정도 민감 테이블을 읽는다.',
  ['직접 권한뿐 아니라 PUBLIC과 상속 역할의 권한을 조사한다.','공통 부여를 필요한 역할로 옮긴 후 새 계정의 접근이 거부되는지 확인한다.'],
  '계정 하나의 직접 부여 내역만으로 실효 권한을 판단할 수 없다.',
  'PUBLIC을 무조건 삭제하면 된다는 생각은 제품의 공통 권한 모델과 의존성을 무시한다.',
  '직접 권한이 없어도 조회가 성공할 수 있는 이유는?', '공통 권한이나 역할 상속으로 실효 권한을 얻을 수 있기 때문이다.');
q('public-inherited','application',2,[15],'직접 조회 권한이 없는 새 계정이 중요 테이블을 읽는다. 먼저 확인할 것은?',[
  ['PUBLIC과 상속 역할의 실효 권한','개별 부여가 없어도 공통·간접 부여가 접근을 허용할 수 있다.'],['비밀번호 복잡도만','신원 확인 수단의 강도는 이미 허용된 조회의 권한 출처를 설명하지 않는다.'],['DB 파일 암호화 알고리즘만','저장 내용 보호와 사용자의 실효 조회 권한은 별도다.'],['백업의 최근 생성 시각만','복구 준비 상태는 현재 사용자의 접근 인가 경로를 보여주지 않는다.']]);
q('public-revoke-scope','application',2,[15],'PUBLIC의 불필요한 조회 권한을 줄이는 적절한 변경은?',[
  ['필요 업무를 확인해 특정 역할로 좁히고 결과를 시험','최소권한을 달성하면서 필요한 공통 기능의 장애를 예방한다.'],['모든 시스템 공통 권한을 검토 없이 삭제','제품 기능과 응용프로그램 의존성을 깨뜨릴 수 있다.'],['공용 비밀번호를 더 길게 변경','공통 객체 권한의 범위는 비밀번호 길이로 줄지 않는다.'],['접근 로그만 중단','권한을 줄이지 않고 오히려 감시를 약화한다.']]);
q('public-new-users','concept',1,[15],'공통 권한의 위험을 새 계정 생성 때도 검토해야 하는 이유는?',[
  ['새 사용자도 공통 부여의 적용 대상일 수 있음','명시적 계정별 부여와 달리 공통 범위는 신규 사용자에게도 영향을 줄 수 있다.'],['새 계정은 반드시 DBA가 되기 때문','기본 권한은 제품과 설정에 따라 다르며 DBA가 필수는 아니다.'],['새 사용자는 암호화를 해제하기 때문','계정 생성이 저장 암호화를 자동 해제하지 않는다.'],['공통 권한은 기존 사용자에게만 보이기 때문','공통 적용 범위를 잘못 한정한 설명이다.']]);
obj('admin-privileges','관리 권한과 운영체제 인증 경계',[16,17,18],
  '응용프로그램이 관리자 권한을 가지면 작은 오류도 전체 DB 삭제로 번질 수 있고, OS 관리자 그룹은 별도 우회 경로가 될 수 있다.',
  ['관리 권한은 필요한 업무와 사람에게만 부여하고 공용 관리 계정보다 개인별 추적 가능한 사용을 설계한다. 응용프로그램에는 일반 업무에 필요한 권한을 먼저 산정한다. 사용자 관리 문장은 제품과 버전에 맞는 지원 인터페이스를 사용하며 내부 권한 테이블을 옛 예시대로 직접 변경하지 않는다.',
   'OS 인증을 사용하는 SYSDBA 접속은 DB 비밀번호를 입력하지 않더라도 OS의 신뢰와 그룹 멤버십에 의존한다. 따라서 비밀번호 입력이 없다는 사실만으로 무인증이라고 단정하지 않는다. 그룹 구성원·원격 경로·인증 설정을 함께 검토하며 불필요한 고권한 경로를 줄이고 복구용 관리 접근도 승인된 절차로 보존한다.'],
  '응용 권한과 관리 권한을 분리하고 DB 밖의 인증 신뢰도 점검한다.',
  [['업무 계정','정해진 자료 작업','주문 조회·등록만 허용'],['관리 계정','DB 운영 작업','승인된 유지보수'],['OS 인증','OS 신뢰에 따른 인증','허가된 관리 그룹 검사']],
  '일반 조회 서비스가 DBA 계정으로 실행되고 있다.',
  ['실제 SQL 작업과 필요한 객체 권한을 조사한다.','전용 업무 계정으로 전환하고 필요한 조회는 성공, 관리 작업은 거부되는지 확인한다.'],
  '업무 기능을 유지하면서 오류와 침해의 영향 범위를 줄인다.',
  'DB 비밀번호 프롬프트가 없으면 아무나 SYSDBA라는 생각은 OS 인증과 그룹 권한을 놓친다.',
  'DB 권한만 회수했는데 OS 그룹에 고권한 사용자가 남았다면 무엇을 점검할까?', 'OS 기반 관리 인증 경로와 그룹 멤버십을 함께 점검한다.', ['db-version','os-auth']);
q('admin-app-minimum','application',2,[16,17],'조회 전용 프로그램이 DBA 권한으로 동작한다. 가장 적절한 개선은?',[
  ['필요 객체의 조회만 가능한 전용 계정으로 전환','프로그램 취약점이 악용되어도 삭제·설정 변경으로 확대되는 경로를 줄인다.'],['DBA 계정 이름만 변경','권한 범위가 그대로여서 피해 가능성은 남는다.'],['공용 DBA를 더 많은 서비스에 사용','공유 범위와 사고 영향을 확대한다.'],['권한 확인을 생략하고 암호화만 추가','암호화는 허가된 관리 작업의 남용을 직접 통제하지 못한다.']]);
q('admin-os-authentication','contrast',2,[18],'DB 비밀번호 없이 OS 인증으로 관리 접속이 성공했다. 가장 정확한 해석은?',[
  ['OS 신뢰와 관리 그룹이 인증 경계이므로 그 구성을 검토','비밀번호 프롬프트 부재가 인증 부재를 뜻하지 않는다. 신뢰한 OS 주체가 적절한지가 핵심이다.'],['누구나 무조건 무인증 접근 가능','접속 조건과 그룹 구성을 확인하지 않은 단정이다.'],['OS 계정은 DB 권한과 항상 무관','일부 관리 인증은 OS 그룹을 직접 신뢰한다.'],['로그 수집만 켜면 과도한 권한이 사라짐','감사는 권한 회수를 대신하지 않는다.']]);
q('admin-personal-account','evidence',1,[16],'관리자들이 하나의 계정을 공유할 때 가장 약해지는 것은?',[
  ['행위의 개인별 책임 추적','같은 계정으로 보이는 행위를 실제 담당자에게 연결하기 어려워진다.'],['테이블 열의 데이터 형식','계정 공유가 열 형식을 바꾸지 않는다.'],['저장 장치의 물리 용량','공유 여부가 디스크 용량을 결정하지 않는다.'],['SQL의 문법 규칙','문법은 계정 공유와 무관하다.']]);
obj('backup-recovery','백업 존재보다 복원 가능성 확인',[19,24],
  '백업 파일이 있어도 읽을 수 없거나 필요한 키가 없으면 장애 때 업무를 되살릴 수 없다.',
  ['백업은 오류·변조·장애로 잃은 상태를 복구하기 위한 수단이다. 업무가 허용하는 손실 시점과 복구 시간에 맞추어 주기와 보관 위치를 정한다. 유지보수 전 전체 백업은 교안의 대표 조치이며 제품의 복구 방식과 일관성 조건을 검토해야 한다.',
   '백업 계정과 매체도 유출·삭제의 대상이다. 접근 제한과 암호화, 분리 보관을 고려하고 복원에 필요한 키와 구성 정보를 안전하게 보존한다. 성공 메시지와 파일 존재는 복원 시험의 대체물이 아니며 시험 환경에서 데이터의 일관성과 응용프로그램 기능을 검증해야 한다.'],
  '백업 성공과 업무 복원 성공을 서로 다른 증거로 남긴다.',
  [['백업 확인','복사 작업과 파일 점검','일정대로 파일 생성'],['복원 검증','되살린 업무 상태 확인','복원 DB의 조회와 정합성 시험']],
  '업그레이드 전 백업 파일이 있지만 복원 시험 이력이 없다.',
  ['필요한 데이터·로그·구성·키가 복구 세트에 포함되는지 확인한다.','격리된 시험 환경에서 복원하여 데이터와 핵심 업무 결과를 검증한다.'],
  '파일 생성만 확인한 상태를 복구 준비 완료로 부르지 않는다.',
  '암호화 백업은 키를 잃어도 복원할 수 있다는 생각은 암호화의 접근 제한 성질과 충돌한다.',
  '백업을 원본과 같은 관리자 권한으로만 보관하면 어떤 위험이 남을까?', '동일 계정 침해가 원본과 백업의 삭제·변조로 함께 이어질 수 있다.');
q('backup-restore-evidence','evidence',2,[19],'백업 준비 상태의 가장 강한 근거는?',[
  ['복원 시험에서 일관된 데이터와 핵심 업무의 동작 확인','실제 복원 가능성과 응용 기능까지 검증해야 복구 목적을 달성했는지 알 수 있다.'],['예약 작업이 정해진 시각에 실행되었다는 이력','실행 시작 이력은 파일 완전성과 복원 결과까지 검증하지 않는다.'],['파일이 하나 존재함','불완전하거나 손상된 파일도 존재할 수 있다.'],['백업 도구가 성공 코드만 반환함','도구 상태는 실제 데이터 복원과 업무 동작의 독립 검증을 대신하지 않는다.']]);
q('backup-key-loss','application',1,[19,24],'암호화한 백업만 남고 복호화 키를 잃었다. 예상되는 문제는?',[
  ['자료가 남아 있어도 내용을 복원하지 못할 수 있음','암호화는 키 없는 해석을 어렵게 하므로 키 복구 계획도 가용성의 일부다.'],['키가 없어도 언제나 자동 해독','그렇다면 키에 의한 보호가 성립하지 않는다.'],['암호문이 자동으로 평문으로 바뀜','키 상실이 데이터를 변환하지 않는다.'],['관리자 이름만 알면 복구 보장','신원 정보만으로 암호키를 대체할 수 없다.']]);
q('backup-upgrade','application',2,[19],'DBMS 유지보수 전에 복구 계획을 확인하는 주된 이유는?',[
  ['변경 실패 시 허용된 시점과 시간 안에 복구하기 위해','변경은 장애를 유발할 수 있으므로 백업과 복원 절차를 사전에 검증해야 한다.'],['업그레이드가 모든 과거 자료를 반드시 삭제하기 때문','위험 대비와 필연적 삭제를 혼동한 주장이다.'],['백업이 접근권한을 자동 정리하기 때문','백업은 권한 최소화 기능을 대신하지 않는다.'],['저장 암호화를 영구 중지하기 위해','유지보수 대비가 암호화 중지를 요구하는 것은 아니다.']]);
obj('service-exposure','샘플·원격 접근과 노출 표면',[20,21],
  '업무에 필요 없는 서비스와 넓은 접속 허용은 공격자가 시도할 수 있는 진입점을 늘린다.',
  ['샘플 DB와 시험 기능은 예제 계정·불필요한 권한·환경 정보를 남길 수 있어 업무 의존성을 확인한 뒤 제거하거나 제한한다. 샘플 존재만으로 이미 유출되었다고 단정하지 않으며 실제 내용·접근 가능성과 설정을 점검한다. 최소 기능은 방어할 표면과 관리 부담을 함께 줄인다.',
   '원격 DB 접속은 허가된 경로와 주체에 한정하고 네트워크 제한과 DB 인증을 함께 적용한다. 접속 출발지의 제한은 인증을 대신하지 않는다. NAT도 주소 변환 기능이므로 방화벽 정책과 동일하지 않으며 허용된 장비가 침해되면 통과한 연결 안에서도 권한 통제가 필요하다.'],
  '불필요한 기능을 줄이고 네트워크 허용과 DB 권한을 별도로 검증한다.',
  [['접속 경로 제한','어디서 연결하는지 통제','업무 서버에서만 DB 접근'],['DB 인증·인가','누가 무엇을 하는지 통제','업무 계정의 특정 조회 허용']],
  'DB가 모든 출발지에 열려 있고 오래된 샘플이 남아 있다.',
  ['실제 업무가 요구하는 출발지·포트·샘플 의존성을 조사한다.','필요 경로만 허용하고 불필요 샘플을 정리한 뒤 허용·거부 접근을 확인한다.'],
  '좁은 접속면과 최소권한을 함께 갖추어야 한다.',
  '사설 주소를 쓰면 인증 없이도 안전하다는 생각은 허용 경로나 내부 침해를 고려하지 않는다.',
  '허용 IP에서 접속한 계정에는 모든 권한을 주어도 될까?', '아니다. 접속 출발지 허용은 DB 객체별 인가를 대신하지 않는다.', ['network']);
q('exposure-sample','application',1,[20],'업무에 쓰지 않는 샘플 DB가 발견되었다. 적절한 조치는?',[
  ['의존성과 노출을 확인하고 불필요한 기능을 정리','불필요한 계정·자료·서비스를 줄이되 정상 업무가 의존하지 않는지 검증한다.'],['샘플이므로 영구 관리자 권한 부여','시험 자료라는 이유로 과도한 접근을 허용할 근거가 없다.'],['존재만으로 개인정보 유출 확정','내용과 접근 증거를 확인하지 않은 단정이다.'],['샘플 이름만 운영으로 변경','실제 노출과 권한을 줄이지 못한다.']]);
q('exposure-ip-auth','contrast',2,[21],'허용된 업무 서버의 IP로 DB 접속이 들어왔다. 다음 판단으로 옳은 것은?',[
  ['인증과 객체별 권한을 계속 확인해야 함','허용 출발지가 곧 모든 동작의 인가를 뜻하지 않으며 서버 침해 가능성도 남는다.'],['모든 삭제 작업 자동 허용','네트워크 허용 범위와 DB 조작 권한은 다르다.'],['계정 식별은 불필요','누가 어떤 작업을 했는지 남기고 인가해야 한다.'],['암호화 키를 평문으로 반환','접속 경로 허용은 비밀정보 공개의 근거가 아니다.']]);
q('exposure-nat','concept',2,[21],'DB 서버를 사설 주소로 바꾸었다. 그 사실만으로 확정할 수 있는 것은?',[
  ['주소 체계가 달라졌으며 접근통제 효과는 경로·정책을 확인해야 함','사설 주소와 NAT는 인증·인가·방화벽 정책의 존재를 자동 보장하지 않는다.'],['모든 원격 접근이 영구 차단됨','포트 전달이나 중계 경로가 있으면 접근할 수 있다.'],['계정 오용이 불가능해짐','주소 변환은 허가된 계정의 행위를 제한하지 않는다.'],['백업 유출도 차단됨','저장 자료의 반출은 별도 경로와 통제의 문제다.']]);
obj('audit-operations','감사 로그의 목적·보호·비용',[22,23],
  '로그를 켰다는 사실보다 어떤 행위를 찾을 수 있고 누가 기록을 바꿀 수 있는지가 사고 조사에 중요하다.',
  ['감사는 로그인, 권한 사용과 객체 작업 중 필요한 사건을 기록해 책임 추적과 이상 징후 분석을 돕는다. 오류 로그는 서버의 시작·종료·문제 상태, 일반 질의 로그는 요청 흐름, 느린 질의 로그는 성능 조건에 따른 질의를 관찰한다. 바이너리 로그는 변경 이벤트의 복제·복구, 릴레이 로그는 복제본이 받은 이벤트의 중계에 쓰인다. 목적이 다르므로 하나를 모든 보안 감사의 대체물로 단정하지 않는다.',
   '기록에는 질의와 개인정보가 들어갈 수 있어 접근 제한, 보존 기간, 저장량과 변조 탐지를 설계한다. Oracle의 OS 감사 저장 위치를 지정하는 설정이 자동 암호화까지 뜻하지는 않는다. 제품의 감사 기능·에디션·버전과 실제 생성 결과를 확인하고 단순한 로깅 활성화를 모든 접근의 완전한 기록으로 과장하지 않는다.'],
  '감사 대상과 조사 질문을 연결하고 기록 자체의 기밀성·무결성도 보호한다.',
  [['보안 감사','주체와 행위의 추적','권한 변경 기록'],['느린 질의 로그','지연 조건의 분석','오래 걸린 질의 조사']],
  '보안 사고 조사에 느린 질의 로그만 남아 있다.',
  ['해당 로그의 수집 조건을 확인해 빠른 조회나 로그인 사건이 빠졌을 수 있음을 인식한다.','조사에 필요한 인증·권한·객체 접근 이벤트를 별도 수집하고 샘플 사건으로 확인한다.'],
  '성능 로그만으로 모든 보안 행위를 복원할 수 없다.',
  'OS에 기록되면 자동으로 암호화되었다는 생각은 저장 위치와 보호 방식을 혼동한다.',
  '감사 로그에 민감한 값이 남으면 무엇을 함께 정할까?', '접근권한, 필요한 수집 범위, 보존·삭제 정책과 변조 방지를 함께 정한다.', ['audit']);
q('audit-purpose','contrast',2,[22,23],'느린 질의 로그만으로 모든 데이터 조회를 감사할 수 없는 이유는?',[
  ['수집 조건이 지연 기준 중심이어서 빠른 행위가 빠질 수 있음','성능 진단용 선별 기록은 모든 인증·인가·객체 접근을 보장하는 감사 정책과 다르다.'],['느린 질의는 항상 악성임','정상 업무도 오래 걸릴 수 있다.'],['빠른 질의는 데이터에 접근하지 않음','실행 시간이 짧아도 민감 자료를 읽을 수 있다.'],['감사 로그는 개인정보를 포함할 수 없음','질의나 식별정보가 담길 수 있으므로 보호해야 한다.']]);
q('audit-os-encryption','evidence',2,[22],'감사 파일 저장 디렉터리가 설정되었다. 추가 근거 없이 주장할 수 없는 것은?',[
  ['감사 파일이 자동으로 암호화되어 있다','경로 설정은 저장 위치를 뜻하며 암호화 여부는 별도의 기능과 실제 구성을 확인해야 한다.'],['저장 위치가 구성 항목이다','그 항목의 목적 자체이므로 타당하다.'],['해당 디렉터리의 접근권한을 검토해야 한다','기록의 기밀성과 무결성을 위해 필요한 점검이다.'],['감사 방식의 버전을 확인해야 한다','통합 감사 등 버전에 따른 설정 차이를 검토하는 것은 타당하다.']]);
q('audit-volume-privacy','application',2,[22,23],'감사 로그 용량이 급증하고 개인 정보도 담긴다. 적절한 운영은?',[
  ['필요 사건·권한·보존 기간·용량 경보를 함께 설계','조사 가능성을 유지하면서 불필요한 수집과 저장 고갈, 기록 노출을 줄이는 조합이다.'],['저장 용량만 늘리고 권한·보존은 무기한 유지','기록 노출과 불필요한 장기 보관 문제는 해결하지 못한다.'],['아무 설명 없이 모든 감사 중단','필요한 사건 증거도 사라진다.'],['암호화만 적용하면 수집 범위와 용량 관리도 불필요','암호화는 적절한 수집·보존·저장 고갈 관리를 대신하지 않는다.']]);
obj('encryption-boundary','암호화가 보호하는 순간과 남는 평문',[24,28],
  '저장 장치 도난에는 강한 암호화도 정상 조회 권한을 악용한 화면 복사에는 효과가 다르다.',
  ['저장 암호화는 키를 얻지 못한 사람이 파일이나 매체만 가져갔을 때 내용을 이해하기 어렵게 한다. TDE처럼 DB가 투명하게 복호화하는 방식에서는 허가된 질의 결과가 평문으로 나올 수 있다. 내부자의 모든 유출을 자동 차단한다는 표현은 보호 경계를 넘어선다.',
   '전송 중 보호는 TLS 같은 통신 보호, 조회 범위는 인가, 결과 반출은 업무 통제와 감사가 맡는다. 현대 보충으로 로그인 비밀번호는 복호화가 필요한 데이터와 구분하여 전용 느린 해시와 솔트를 사용하는 검증값 저장을 고려한다. 법적 암호화 대상과 요구 방식은 적용 시점·규정에 따라 확인하며 교안의 목록을 최신 법률의 완결된 목록으로 채점하지 않는다.'],
  '암호문이 어디서 평문이 되고 누가 그 결과와 키에 접근하는지 추적한다.',
  [['저장 암호화','파일·매체 내용 보호','도난 백업의 해석 제한'],['전송 보호','통신 경로 보호','DB 연결의 TLS'],['인가','정상 질의 범위 제한','고객별 조회 제한']],
  '저장 파일은 암호화되어 있지만 상담 직원이 전체 고객을 조회한다.',
  ['직원이 받는 결과는 권한에 따라 복호화된 평문임을 확인한다.','조회 범위를 줄이고 대량 반출 감사를 추가하며 저장 암호화는 유지한다.'],
  '암호화와 최소권한은 서로 다른 유출 경로를 줄이는 보완 수단이다.',
  '비밀번호도 복호화해서 비교해야 한다는 생각은 인증 검증값과 복원이 필요한 업무자료의 목적을 혼동한다.',
  'TDE를 켰으니 모든 사용자에게 전체 조회를 줘도 될까?', '아니다. 투명 복호화 후의 접근과 반출을 인가·감사로 제한해야 한다.', ['encryption','password-storage']);
q('crypto-authorized-read','application',2,[24],'TDE 적용 뒤 정당한 조회 권한이 있는 내부자가 결과를 반출했다. 옳은 분석은?',[
  ['정상 복호화된 결과의 반출은 별도 접근·업무 통제가 필요','TDE의 저장매체 보호와 허가된 질의 결과의 사용 통제는 다른 경계다.'],['암호화 알고리즘이 반드시 깨졌다','정상 복호화된 결과를 가져갔을 수 있어 암호 해독의 증거가 아니다.'],['저장 암호화를 무조건 폐기해야 한다','매체 도난 등의 보호 효과는 여전히 남는다.'],['암호화가 있으므로 유출은 불가능하다','발생한 행위와 보호 범위를 무시한 주장이다.']]);
q('crypto-password-storage','contrast',2,[28],'현대 보충 설명에서 로그인 비밀번호와 복원이 필요한 고객 주소를 구분하는 이유는?',[
  ['비밀번호는 검증이 목적이며 주소는 업무상 복원이 필요할 수 있음','비밀번호는 적절한 솔트·느린 해시를, 복원이 필요한 자료는 키 관리가 있는 암호화를 검토하는 등 목적이 다르다.'],['모든 자료에 단순 MD5만 쓰면 되기 때문','빠른 일반 해시 하나로 인증 저장과 업무 복원을 모두 만족할 수 없다.'],['주소는 언제나 공개 정보이기 때문','개인 주소의 보호 필요성을 무시한다.'],['비밀번호는 반드시 원문으로 보관해야 하기 때문','비교를 위해 원문을 저장할 필요는 없으며 노출 피해가 커진다.']]);
q('crypto-transit-at-rest','contrast',1,[24],'도난 백업 파일의 내용 보호와 DB 연결 도청 방지를 각각 맡는 조합은?',[
  ['저장 암호화와 통신 암호화','자료가 놓인 매체와 전송 경로는 서로 다른 노출 지점이므로 각각 보호해야 한다.'],['통신 암호화 하나로 두 위치 모두 자동 보호','통신이 끝나 저장된 파일의 암호화는 별도다.'],['감사 로그와 접근 시도 횟수 제한','감사·시도 제한은 조사와 온라인 추측 통제이며 도난 매체·전송 내용의 암호 보호와 다르다.'],['주소 변환과 계정 이름 변경','주소와 이름 변경은 내용의 기밀성을 암호학적으로 보호하지 않는다.']]);
obj('crypto-db-integration','DB 연동 암호화의 실행 위치',[4,6,24,25,26],
  '응용 코드를 크게 바꾸기 어려운 기존 시스템에서도 암호화할 수 있지만 DB 내부에서 평문이 보이는 경계를 알아야 한다.',
  ['교안의 DB 연동 그림은 DB 측 커넥터나 모듈이 암·복호화를 요청하는 위치를 보여 준다. 하드웨어 방식에서는 별도 장비로 처리를 위임하는 구성이, 소프트웨어 방식에서는 DB 측 실행 모듈과 정책 서버를 연계하는 구성이 예시다. 이는 DAC·MAC·RBAC와 다른 실행·배치 분류다.',
   'DB 연동은 응용 변경을 줄일 수 있으나 제품별 설치, 드라이버·DB 버전, 질의와 인덱스 지원을 확인해야 한다. 별도 암호 장비를 사용해도 요청 권한과 키 관리가 느슨하면 정상 경로로 복호화될 수 있다. 교안의 제품별 토큰·키 그림은 일반 암호 시스템이 모두 같은 키 저장 방식을 쓴다는 뜻이 아니다.'],
  'DB 연동의 장점은 응용 변경 완화이며 키 경계·지원 버전·성능은 별도 검증한다.',
  [['H/W DB 연동','DB가 별도 암호 장비에 요청','DB 커넥터와 암호 장비 연결'],['S/W DB 연동','DB 측 모듈에서 처리','정책 서버와 연계한 DB 모듈']],
  '응용 코드 수정이 어려운 시스템에 DB 연동 암호화를 검토한다.',
  ['DB 커넥터와 지원 버전, 암·복호화가 실행되는 경계를 확인한다.','대표 질의·인덱스·대량 처리와 장애 시 동작을 시험해 적용 가능성을 판단한다.'],
  '코드 수정 최소화 가능성과 실제 무수정·무성능저하 보장은 구분한다.',
  'H/W 방식이면 접근권한 없이도 언제나 안전하다는 생각은 암호 장비에 대한 정상 요청 경계를 놓친다.',
  'RBAC와 DB 연동을 하나의 양자택일 분류로 비교해도 될까?', '아니다. RBAC는 권한 부여 모형이고 DB 연동은 암호 처리 위치다.', ['integration']);
q('crypto-independent-axes','contrast',1,[4,6,25,26],'RBAC와 H/W DB 연동을 함께 사용하는 설계에 대한 옳은 설명은?',[
  ['권한 결정 모형과 암호 실행 배치가 다른 축이므로 병용 가능','RBAC는 누가 어떤 권한을 갖는지, DB 연동은 어느 구성요소가 암호 처리를 요청하는지를 다룬다.'],['두 방식은 같은 분류여서 하나만 선택','인가와 실행 위치를 혼동한다.'],['H/W 연동이 자동으로 모든 역할을 만든다','장비 배치가 직무 권한을 정의하지 않는다.'],['RBAC가 암호키 저장 장비의 이름이다','RBAC는 역할 기반 접근통제 모형이다.']]);
q('crypto-db-connector','evidence',2,[25,26],'교안의 H/W DB 연동 그림에서 암호 처리 요청의 연동 지점은?',[
  ['DB 측 커넥터와 별도 암호 장비 사이','그림은 DB 측 커넥터가 장비에 암·복호화를 요청하는 구성을 표현한다.'],['응용 코드의 SDK와 응용 측 에이전트 사이만','이는 응용 연동 예시와 가깝고 질문은 H/W DB 연동의 요청 지점이다.'],['RBAC 역할 계층과 세션 사이','이는 권한 모델의 관계이며 암호 장비 요청 경로가 아니다.'],['DB와 사용자 브라우저 사이의 TLS 종료 지점만','전송 보호의 종단과 저장 암호화의 DB 커넥터 요청을 혼동한 설명이다.']]);
q('crypto-db-compatibility','application',2,[24,25,26],'DB 연동으로 응용 변경을 줄이려 한다. 가장 필요한 사전 확인은?',[
  ['DB 버전·질의·인덱스 지원과 성능·장애 동작','연동 목적이 같아도 제품 제약과 처리 비용이 달라 실제 업무 경로를 검증해야 한다.'],['장비 외형만 확인','외형은 호환성과 질의 결과를 보장하지 않는다.'],['응용 변경이 없으므로 시험 생략','변경이 작아도 질의·복원·성능에 영향이 있을 수 있다.'],['H/W면 키 관리 검토 생략','외부 장비도 요청 권한과 키 수명·가용성 관리가 필요하다.']]);
obj('crypto-app-integration','응용 연동 암호화와 키 경계',[25,26,27],
  'DB에 보내기 전에 암호화하면 DB에 평문을 줄일 수 있지만 응용과 키 서비스가 새로운 중요 경계가 된다.',
  ['교안의 응용 연동은 응용 서버가 커넥터·SDK를 통해 암호 처리를 요청하는 구성이다. H/W 응용 연동은 별도 암호 장비를 호출하고 S/W 응용 연동은 응용 측 라이브러리나 에이전트와 정책 서버를 연결하는 예시다. DB 연동과 비교하면 코드 수정과 데이터 형식 처리가 필요할 수 있다.',
   '응용에서 먼저 암호화하면 DB 저장·조회 기능과 검색 인덱스에 제약이 생길 수 있다. 또한 입력·출력·로그에는 평문이 남을 수 있어 암호 호출 이전과 이후를 함께 조사한다. 키·토큰의 노출, 키 서비스 장애와 교체 시 기존 자료 복호화 가능성은 별도로 검증하며 특정 제품 그림을 모든 구현의 표준으로 일반화하지 않는다.'],
  'DB 밖으로 암호 경계를 옮기면 응용 코드·키 요청·로그·검색을 함께 설계한다.',
  [['DB 연동','DB 측에서 암호 처리 요청','기존 응용 변경 완화'],['응용 연동','응용이 암호 처리 호출','SDK 통합과 자료 흐름 변경']],
  '응용 SDK로 고객 연락처를 암호화했는데 디버그 로그에는 원문이 남는다.',
  ['암호 호출 전에 원문을 기록하는 지점을 찾아 데이터 흐름을 그린다.','불필요한 원문 기록을 제거·마스킹하고 저장 자료뿐 아니라 로그·오류 경로도 확인한다.'],
  'DB 암호화 성공이 응용의 모든 평문 사본 보호를 뜻하지 않는다.',
  '키 서버를 분리하면 응용 침해의 복호화 요청도 자동 차단된다는 생각은 정상 권한 악용을 놓친다.',
  '키 서비스가 멈추면 암호화된 업무에는 어떤 영향이 있을까?', '필요한 암·복호화가 실패해 업무 가용성이 영향을 받을 수 있어 복구·장애 정책이 필요하다.', ['integration']);
q('crypto-app-sdk','contrast',1,[26,27],'응용 서버가 SDK를 호출하여 암호화한 값을 DB에 보내는 방식은?',[
  ['응용 연동 방식','암호 호출의 통합 지점이 응용 코드와 SDK이므로 응용 연동이다. H/W·S/W 여부는 실행 자원에 따라 다시 나뉜다.'],['MAC만을 의미','보안등급 인가 모형과 암호 호출 위치는 다르다.'],['모든 DB 연동 방식','이 사례의 호출 지점은 DB 내부가 아니라 응용이다.'],['감사 설정만을 의미','SDK 암호 처리는 로그 수집 설정과 다르다.']]);
q('crypto-app-plaintext-log','application',2,[25,27],'응용에서 암호화하기 직전 입력값을 로그에 남긴다. 남은 문제는?',[
  ['DB 외부의 평문 로그도 보호·최소화해야 함','저장 DB가 암호화되어도 호출 전의 평문 사본이 별도 노출 경로가 된다.'],['암호화 알고리즘이 반드시 틀림','올바른 암호화와 별개로 로그가 원문을 남길 수 있다.'],['DB 인덱스가 반드시 삭제됨','평문 로그 문제로 인덱스 삭제를 단정할 수 없다.'],['키 서버가 있으니 원문 로그는 안전함','키 서비스는 이미 기록한 평문을 보호하지 않는다.']]);
q('crypto-app-key-availability','application',2,[26,27],'외부 키 서비스가 장애일 때 응용의 복호화가 멈춘다. 설계에서 보완할 것은?',[
  ['승인된 키 복구·가용성·장애 처리와 검증','암호의 기밀성을 유지하면서 정당한 업무가 복구될 수 있는 계획이 필요하다.'],['키를 공개 화면에 게시','가용성을 위해 비밀성을 포기하는 잘못된 처리다.'],['암호문을 평문이라고 표시','표시만 바꿔서는 복호화되지 않는다.'],['모든 자료를 무조건 폐기','복구 가능한 장애를 데이터 손실로 확대한다.']]);
obj('crypto-rollout','암호화 전환과 검증 순서',[24,28],
  '전환이 끝났다는 메시지만 믿으면 일부 자료의 변환 실패나 검색 성능 저하를 운영에서 뒤늦게 발견할 수 있다.',
  ['암호화 대상은 보호 필요성과 적용 규정을 바탕으로 정하고, 선택한 방식의 형식·인덱스·성능 제약을 평가한다. 교안의 적용 방향은 DB 환경, 임시 공간, 패치 수준과 작업 시간을 확인하도록 한다. 대상이 많을수록 언제나 같은 비율로 느려진다고 단정하지 말고 실제 질의와 실행 위치로 측정한다.',
   '전환 전에는 복구 가능한 백업과 키 복구를 검증하고 변환 중 일관성·실패 처리·중단 시 복구를 계획한다. 전환 후에는 데이터의 정확성, 응용 기능, 성능을 각각 시험한다. 병렬 처리는 작업 시간을 줄일 수 있지만 자원 경쟁과 동시 변경의 영향을 고려해야 하며 성공 여부를 파일 수나 도구 메시지만으로 판단하지 않는다.'],
  '정확성·업무 기능·성능·복구를 각각 확인한 뒤 전환을 완료로 판단한다.',
  [['정확성 시험','자료가 올바르게 변환·복원되는지','표본과 경계값 대조'],['성능 시험','대표 업무의 지연·처리량','검색·대량 처리 측정']],
  '암호화 전환 후 일부 검색 결과가 누락되고 응답이 느려졌다.',
  ['원래 자료와 변환 결과의 정합성, 검색·인덱스 지원 여부를 먼저 비교한다.','대표 업무 지연과 자원 사용을 측정하고 승인된 복구·개선 절차를 적용한다.'],
  '변환 완료와 운영 적합성은 별도 검증 결과다.',
  '비업무 시간 병렬 처리면 언제나 안전하다는 생각은 자원 부족과 실패 복구 문제를 놓친다.',
  '전환 도구가 성공을 보고했어도 남은 검증 세 가지는?', '자료 정확성, 응용 기능, 실제 성능이며 복구 가능성도 유지해야 한다.');
q('rollout-data-validation','evidence',2,[28],'암호화 도구가 성공을 보고했다. 자료 정확성을 확인하는 다음 단계는?',[
  ['복호화한 결과와 원본의 정합성·경계값을 대조','도구 상태와 실제 자료 변환의 정확성은 별도 증거이므로 실제 결과를 비교해야 한다.'],['성공 문구를 더 크게 표시','표시는 정확성 검증을 추가하지 않는다.'],['백업을 즉시 모두 삭제','문제를 발견했을 때 복구 경로를 잃는다.'],['성능만 보고 값 비교 생략','빠른 응답이 올바른 자료를 뜻하지 않는다.']]);
q('rollout-index-performance','application',2,[24,28],'암호화 뒤 특정 검색만 느려졌다. 우선 조사할 내용은?',[
  ['해당 방식의 인덱스 지원과 실행 계획·질의 지연','검색 처리와 암·복호화 비용이 방식별로 달라 실제 업무 경로로 원인을 좁혀야 한다.'],['무조건 사용자 수가 원인이라고 단정','조건을 비교하지 않은 원인 추정이다.'],['모든 암호화는 무성능저하라고 선언','교안도 성능과 DB 제약 검토를 요구한다.'],['DB 계정 수만 줄여 종료','검색 제약과 실행 비용을 직접 확인하지 못한다.']]);
q('rollout-parallel-resource','application',2,[28],'암호화 전환을 병렬화하기 전 확인할 조건으로 가장 적절한 것은?',[
  ['임시 공간·자원 경쟁·중단 복구와 허용 작업 시간','동시 작업이 늘면 자원을 더 사용하고 실패 처리가 복잡해질 수 있어 실행 환경을 검증해야 한다.'],['병렬이면 백업이 불필요함','처리 속도와 복구 준비는 무관하다.'],['병렬이면 모든 제품의 제약이 사라짐','병렬 처리가 호환성과 질의 제약을 해결하지 않는다.'],['암호키를 모든 작업 로그에 출력','키 노출은 전환에 필요한 성능 검증이 아니며 보호를 무너뜨린다.']]);
obj('key-lifecycle','키 수명과 복구를 함께 설계하기',[24,25,26,27,28],
  '암호문만 복사해 보호했다고 생각하면 키를 함께 유출하거나 잃는 순간 보호와 복구를 동시에 실패할 수 있다.',
  ['암호화는 데이터와 별개로 키를 사용할 권한에 의존한다. 교안의 장비·정책 서버 그림을 읽을 때는 어느 구성요소가 요청하고 누가 승인하는지를 확인해야 한다. 키나 토큰을 소스·일반 로그에 남기면 데이터 파일을 분리해도 다른 경로로 해독할 수 있는 위험이 생긴다.',
   '현대 보충으로 키 생성·보관·사용·교체·폐기와 복구를 수명 전체에서 관리한다. 키 교체는 새 자료에 새 키를 적용하는 일과 옛 자료를 읽을 수 있도록 이전 키를 보호하는 일을 구분해야 한다. 암호문과 키 사본을 같은 권한으로 무제한 공개하지 않으면서도 승인된 복구가 가능한지 시험해야 한다.'],
  '암호화 대상뿐 아니라 키를 누가 언제 어떻게 사용할 수 있는지 기록한다.',
  [['키 접근통제','복호화 능력의 사용 제한','업무 역할별 요청 제한'],['키 복구','정당한 복호화의 지속','보호된 복구 절차 시험']],
  '키를 교체한 뒤 이전 달의 암호화 백업을 복원하려 한다.',
  ['백업이 어떤 키 버전에 의존하는지 확인한다.','승인된 절차로 해당 키를 이용해 복원을 시험하고 더 이상 필요 없는 키의 폐기 조건을 정한다.'],
  '새 키 발급만으로 옛 자료 복구와 폐기 정책이 완성되지 않는다.',
  '키는 바꾸기만 하면 옛 키를 바로 지워도 된다는 생각은 과거 자료의 복구 의존성을 놓친다.',
  '암호문과 키를 누구나 읽는 폴더에 같이 두면 어떤가?', '키 없는 해석을 막는 경계가 무너지므로 자료와 키의 접근권한을 분리해야 한다.', ['integration']);
q('key-co-location','application',1,[24,26,27],'암호화 백업과 복호화 키를 같은 공개 폴더에 보관한다. 핵심 위험은?',[
  ['백업을 얻은 사람이 키도 얻어 내용을 해석할 수 있음','암호문 보호는 키의 비밀성과 사용 통제에 의존한다. 두 자료의 무제한 공동 공개는 이 경계를 무너뜨린다.'],['암호문 길이가 자동으로 0이 됨','공개 위치가 파일 길이를 바꾸지 않는다.'],['백업 시간이 반드시 빨라짐','접근권한 구성과 처리 속도는 다른 문제다.'],['모든 DB 권한이 자동 회수됨','키 보관 위치는 DB 인가 목록을 변경하지 않는다.']]);
q('key-rotation-old-data','application',2,[28],'새 키를 발급한 뒤 이전 키를 즉시 폐기하기 전에 확인할 것은?',[
  ['이전 키에 의존하는 자료·백업의 복구 필요성','남은 암호문이 옛 키를 필요로 하면 키 폐기가 자료 접근 상실로 이어질 수 있다.'],['새 키로 신규 쓰기가 성공했는지만','새 자료 처리 성공은 이전 자료·백업의 재암호화나 복구 가능성을 입증하지 않는다.'],['새 키의 파일 생성 시각만','생성 사실만으로 옛 자료가 새 키로 전환되었다고 볼 수 없다.'],['현재 온라인 DB에 접속되는지만','온라인 자료가 읽혀도 보관 중인 이전 백업이 다른 키를 요구할 수 있다.']]);
q('key-request-boundary','evidence',2,[25,26,27],'키 서비스를 따로 설치했다. 실제 보호 경계 검증에 필요한 질문은?',[
  ['어떤 주체가 어떤 조건으로 복호화 요청을 승인받는가','서비스 분리만으로 권한이 좁아지지는 않는다. 요청자의 실효 권한과 감사가 핵심이다.'],['암호문 길이가 원문보다 늘었는가만','암호문의 형식·길이만으로 키 요청 권한이 제한되었는지 알 수 없다.'],['키 서버와 DB의 IP가 다른가만','장비 주소 분리와 복호화 승인 범위는 다른 증거다.'],['장비 구입 시 키 관리 기능이 표시되었는가만','기능 보유와 실제 설정·사용 권한의 검증은 다르다.']]);
