// Independent peer review: explicit replacements of unrelated distractors.
// No questions or variants are generated here; IDs and answer positions remain stable.
const peerReviewedQuestions=new Set();
const peerReviewedOptions=new Set();
function reviseWrong(id, replacements) {
  const question=weeks.flatMap(w=>w.questions).find(q=>q.id===id);
  assert(question,`unknown peer-review question ${id}`);
  for(const [optionId,[text,explanation]] of Object.entries(replacements)){
    assert.notEqual(optionId,question.answerId,`${id}: do not overwrite correct choice`);
    const option=question.options.find(o=>o.id===optionId);
    assert(option,`${id}: missing option ${optionId}`);
    option.text=text;option.explanation=explanation;peerReviewedOptions.add(`${id}:${optionId}`);
  }
  peerReviewedQuestions.add(id);
}
