reviseWrong('w07-q042',{a:['한 번 정상으로 판정한 IP의 이후 요청은 모두 검사 생략','같은 출발지에서도 정상·위험 요청이 섞일 수 있어 선택 통제 요구를 충족하지 못한다.'],d:['허용 서비스 포트가 같으면 요청 내용 검사는 생략','같은 IP·서비스 안에서 요청 문맥을 구분해야 하므로 포트만으로 충분하지 않다.']});
reviseWrong('w07-q043',{a:['서버 CPU가 정상이면 회선 포화는 서비스에 영향을 주지 않기 때문','서버 앞의 링크가 병목이면 서버 자원과 무관하게 정상 요청이 도달하기 어렵다.'],b:['IPS가 버린 바이트는 이미 점유한 외부 회선 용량도 즉시 돌려주기 때문','내부 장비가 폐기해도 그 장비까지 오기 위해 소비한 상위 링크 용량은 복구되지 않는다.'],d:['내부 폐기 로그가 있으면 상위 회선 완화도 완료된 것으로 보기 때문','내부 집행 결과만으로 상위 병목이 해소됐는지는 알 수 없다.']});
reviseWrong('w07-q044',{b:['정상 요청 한 건 차단으로 악성 요청에 대한 재현율까지 계산 가능','정상 오탐 사례만으로 실제 공격 전체의 탐지 비율을 계산할 수 없다.'],c:['보안 경보가 남았으므로 거래 실패는 가용성 평가에서 제외','정상 업무의 전달을 막았으므로 보안 조치로 인한 가용성 피해도 평가해야 한다.']});
reviseWrong('w07-q046',{d:['장비를 우회해도 기존 IPS 정책은 같은 수준으로 계속 집행됨','우회 시 검사 공백이 발생할 수 있어 다른 통제와 복구 계획을 함께 설명해야 한다.']});
reviseWrong('w07-q047',{a:['허용 포트만으로 웹 요청의 모든 필드가 이미 검증되기 때문에','포트 허용은 요청 내용의 안전성과 업무 문맥을 검증하지 않는다.'],d:['WAF가 사용자별 모든 업무 인가를 대신 결정하기 때문에','WAF는 웹 문맥의 보완 통제이며 응용의 업무 권한 검사를 대체하지 않는다.']});
reviseWrong('w07-q049',{c:['서버 인증서가 유효하다는 사실만','인증서의 유효성과 WAF가 승인된 위치에서 평문을 보고 실제로 검사했는지는 별개다.']});
reviseWrong('w07-q050',{a:['서로 다른 표현의 경보 수가 같으면 같은 의미로 해석됐다고 확정','같은 건수는 비교한 버퍼와 종단 의미가 일치했다는 증거가 아니다.'],d:['현재 경보가 없는 표현 하나를 정상 기준으로 삼아 모든 예외를 확대','누락인지 정상인지 해석을 먼저 확인해야 하며 광범위한 예외는 보호 공백을 키운다.']});
reviseWrong('w07-q051',{a:['관리 화면의 정책 적용 성공 표시만','정책 적용 상태와 해당 요청이 실제로 차단됐는지는 다르므로 전달 결과가 필요하다.']});

reviseWrong('w05-q005',{c:['사용자 수가 줄었으므로 역할에 모인 권한의 적정성은 검토 불필요','역할 구조를 사용해도 해당 역할의 업무에 필요한 권한만 주는지 평가해야 한다.'],d:['감사 로그가 있으므로 역할의 과도한 권한은 그대로 유지해도 됨','추적 통제는 과도한 작업 권한을 사전에 제한하는 인가를 대체하지 않는다.']});
reviseWrong('w05-q007',{d:['현직자의 비밀번호로 바꿔 퇴직자 계정을 계속 공동 사용','인증정보 교체만으로 계정의 업무 필요성과 소유자·책임 추적 문제가 해결되지 않는다.']});
reviseWrong('w05-q008',{b:['관리 계정의 실패 시도만 기록하고 성공한 작업은 감사하지 않음','필요한 관리 계정을 유지해도 실제 중요 작업의 주체·범위를 추적할 통제가 필요하다.']});
reviseWrong('w05-q012',{a:['옛 설치 예시가 실행되면 지원 버전·인증 적용 범위는 확인하지 않음','명령 실행 성공만으로 대상 버전의 지원 방식과 실제 정책 적용이 검증되지 않는다.']});
reviseWrong('w05-q014',{d:['이름만 바꾸고 다른 식별자·연락처는 실제 값 유지','이름 치환만으로 개인이 재식별되지 않는다고 보장할 수 없으며 불필요한 실제 신원을 가져올 이유가 없다.']});
reviseWrong('w05-q016',{a:['직접 GRANT 목록에 없으므로 조회 성공은 조사하지 않음','실효 권한은 직접 부여 외에 역할·공통 권한 등으로 얻을 수 있으므로 조회 경로를 확인해야 한다.'],b:['계정 비밀번호만 변경하면 상속된 조회 권한도 회수됨','비밀번호 변경은 인증정보를 바꾸지만 역할·공통 범위의 인가를 자동 회수하지 않는다.'],c:['테이블 소유자 이름이 다르므로 공통 권한의 적용은 배제','소유자와 달라도 공통 범위·역할을 통해 조회할 수 있어 실효 권한을 검토해야 한다.']});
reviseWrong('w05-q017',{d:['새 계정에만 직접 거부를 설정하고 기존 공통 조회 권한은 방치','문제는 불필요한 공통 조회 권한 자체이므로 적용 대상·의존성을 검토해 그 권한을 줄여야 한다.']});
reviseWrong('w05-q024',{a:['복구 자료가 존재하면 서비스 중단 허용 시간은 검토하지 않아도 되기 때문','자료 사본과 요구 시간 내 복구 가능성은 별개이며 작업 실패·호환성·키 의존성도 확인해야 한다.']});
reviseWrong('w05-q030',{d:['저장 공간 경보가 사라질 때까지 모든 감사 항목을 무기한 끔','필요 기록을 구분하지 않은 중단은 조사 공백을 만든다. 수집 범위와 용량·권한·보존을 함께 조정해야 한다.']});
reviseWrong('w05-q048',{c:['릴레이 로그는 원본 서버의 모든 읽기 질의를 새로 수집한 감사 목록','릴레이 로그는 복제 원본의 변경 이벤트를 받아 적용에 사용하는 기록이며 모든 조회 감사의 대체물이 아니다.']});
reviseWrong('w05-q046',{d:['사용자가 가진 객체별 capability 증명만으로 등급 비교 없이 결정','문제는 중앙 강제 등급 비교가 핵심이므로 사용자 소지의 객체별 접근 능력만으로 결정하는 설명과 다르다.']});
const reviewedWeek=weeks.find(w=>w.number===7);
const hostNetworkObjective=reviewedWeek.objectives.find(o=>o.id==='w07-hids-nids');
hostNetworkObjective.pages.push(12);
reviewedWeek.coverage.find(c=>c.pages.includes(12)).objectiveIds.push(hostNetworkObjective.id);
hostNetworkObjective.explanation.push('IDS가 모은 요청 내용과 계정·주소 등의 기록에는 개인정보나 업무 비밀이 포함될 수 있다. 기록이 많을수록 항상 좋은 것이 아니라 조사 목적에 필요한 필드로 수집을 최소화하고, 원격 수집·저장 과정의 기밀성과 조회 권한을 보호해야 한다. 조사·보존 의무와 운영 목적을 고려해 보존 기간과 안전한 폐기 절차를 정하고, 사건 보존이 필요한 기록은 승인된 절차로 별도 관리한다. 이는 기록 위·변조 방지와 다른 보호 목표이며 두 가지를 함께 설계해야 한다.');
hostNetworkObjective.comparison.push({term:'기록의 기밀성',meaning:'수집한 민감 정보의 비인가 노출 제한',example:'필요 필드 최소 수집·조회 권한·보존 기간 관리'});
hostNetworkObjective.workedExample.steps.push('내용 원문을 무조건 복제하지 말고 조사에 필요한 필드를 정해 수집하며 중앙 기록의 열람 권한과 보존·폐기 절차도 함께 확인한다.');
hostNetworkObjective.commonMistakes.push('중앙에 모으면 개인정보 문제도 자동 해결된다는 생각은 수집 범위와 중앙 저장소의 접근 권한·보존 위험을 놓친다.');
hostNetworkObjective.check={prompt:'IDS 기록은 왜 중앙 수집 외에 수집 범위·조회 권한·보존도 정해야 할까?',answer:'침해된 호스트의 기록 훼손을 줄이는 것과 수집된 개인정보의 노출을 막는 것은 다른 목표다. 필요한 필드만 수집하고 권한과 보존·폐기를 제한해야 한다.'};
reviewedWeek.references.push({title:'NIST SP 800-92 로그 기밀성·저장·폐기 관리',url:'https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-92.pdf'});
const optionsObjective=reviewedWeek.objectives.find(o=>o.id==='w07-snort-options');
optionsObjective.explanation.push('Snort 3의 flow에서 established는 성립한 TCP 연결의 상태를 요구하고 stateless는 스트림 상태와 관계없이 평가하도록 한다. stateless가 상태 추적 기능의 고장이나 악성 확정, 무조건 허용을 뜻하는 것은 아니다. 상태와 무관하게 평가하더라도 지정한 헤더·내용·다른 조건과 규칙 동작은 여전히 구분해 읽어야 하므로 검색 버퍼의 패턴 일치도 따로 확인한다.');
optionsObjective.comparison.push({term:'established / stateless',meaning:'성립한 TCP 연결 상태 요구 / 스트림 상태와 무관하게 평가',example:'같은 내용 조건이라도 상태 조건에 따라 평가 대상이 달라짐'});
optionsObjective.check={prompt:'stateless면 내용 조건도 생략하고 무조건 허용할까?',answer:'아니다. 스트림 상태와 무관하게 평가한다는 뜻이며 헤더·내용 조건과 alert·drop 등의 지정 동작을 대체하지 않는다.'};
const stateQuestion=reviewedWeek.questions.find(q=>q.id==='w07-q039');
stateQuestion.prompt='Snort 3 flow의 established와 stateless를 비교한 설명으로 옳은 것은?';
Object.assign(stateQuestion.options.find(o=>o.id===stateQuestion.answerId),{text:'established는 성립한 TCP 연결 상태를 요구하고 stateless는 스트림 상태와 무관하게 평가',explanation:'두 조건은 상태의 적용 범위를 정한다. stateless도 헤더·내용 조건을 없애거나 요청을 자동 허용하는 뜻은 아니다.'});
stateQuestion.explanation=stateQuestion.options.find(o=>o.id===stateQuestion.answerId).explanation;
console.log(JSON.stringify({peerReview:weeks.map(w=>({week:w.id,questions:w.questions.filter(q=>peerReviewedQuestions.has(q.id)).length,wrongOptions:[...peerReviewedOptions].filter(id=>id.startsWith(w.id+'-')).length})),wrongOptionsRevised:peerReviewedOptions.size}));
// BUILD_OUTPUT: Explicit authored records above are serialized, never expanded.
for (const w of weeks) {
  validateWeek(w);
  const target={5:45,6:50,7:50}[w.number];
  assert(w.questions.length>=target,`${w.id}: minimum ${target}`);
  const objectiveIds=new Set(w.objectives.map(o=>o.id));
  for(const o of w.objectives) {
    assert(w.questions.filter(q=>q.objectiveId===o.id).length>=3,`${o.id}: three questions`);
    assert(o.prerequisites.every(p=>objectiveIds.has(p)),`${o.id}: local prerequisites`);
    assert(o.explanation.every(p=>(p.match(/[가-힣]/g)||[]).length>=25),`${o.id}: Korean explanatory paragraphs`);
  }
  assert.equal(new Set(w.questions.map(q=>q.prompt)).size,w.questions.length,'duplicate prompt');
  assert.equal(new Set(w.questions.map(q=>q.family)).size,w.questions.length,'families are independent problems');
  for(const o of w.objectives) for(const p of o.pages) assert(w.coverage.some(c=>c.pages.includes(p)&&c.objectiveIds.includes(o.id)),`${o.id}: page ${p} mapping`);
  for(const q of w.questions) for(const p of q.sourcePages) assert(w.coverage.some(c=>c.pages.includes(p)&&c.objectiveIds.includes(q.objectiveId)),`${q.id}: question page ${p} mapping`);
  const output=`dist/content/week-${String(w.number).padStart(2,'0')}.json`;
  writeFileSync(output,JSON.stringify(w,null,2).replace(/\n/g,'\r\n')+'\r\n','utf8');
  const bytes=readFileSync(output), rendered=bytes.toString('utf8');
  assert(!bytes.subarray(0,3).equals(Buffer.from([239,187,191])),'UTF-8 without BOM');
  assert(!/(?<!\r)\n/.test(rendered),'CRLF only');
  assert(!rendered.includes('\uFFFD'),'no replacement characters');
  assert.deepEqual(JSON.parse(rendered),w);
  console.log(JSON.stringify({week:w.id,objectives:w.objectives.length,questions:w.questions.length,corrections:w.corrections.length,pages:w.coverage.length,validateWeek:true}));
}
